await Bun.$`rm -rf ${d} && mkdir -p ${d}/src && cp src/parser_a.rs src/parser_b.rs ${d}/src/`;
await Bun.write(d+"/Cargo.toml", `[package]\nname="v"\nversion="0.1.0"\nedition="2021"\n[dependencies]\n`);
await Bun.write(d+"/src/main.rs", `mod parser_a; mod parser_b;
use parser_a::*; use parser_b::*;
fn toks(s:&str)->Vec<String>{ s.split_whitespace().map(String::from).collect() }
fn ev_a(e:&Expr)->i64{ match e { Expr::Number(n)=>*n, Expr::Binary(l,o,r)=>{let (a,b)=(ev_a(l),ev_a(r)); if *o=='+'{a+b}else{a-b}}}}
fn ev_b(e:&AstNode)->i64{ match e { AstNode::Val(n)=>*n, AstNode::Op(o,l,r)=>{let (a,b)=(ev_b(l),ev_b(r)); if *o=='+'{a+b}else{a-b}}}}
fn main(){
 for s in ["1+2","1 + 2","1+2-3","10-2-3","1+2x","","1+"] {
  let mut p=RecursiveDescentParser::new(s);
  let a=p.parse();
  let av=a.as_ref().map(|e|ev_a(e));
  let b=ShiftReduceParser::parse(&toks(&s.replace("+"," + ").replace("-"," - ")));
  let bv=b.as_ref().map(|e|ev_b(e));
  println!("{:?}\\n  A: {:?} => {:?}\\n  B: {:?} => {:?}", s, a, av, b, bv);
 }
 println!("B unknown token: {:?}", ShiftReduceParser::parse(&["1".into(),"*".into(),"2".into()]));
 println!("B 1 + : {:?}", ShiftReduceParser::parse(&["1".into(),"+".into()]));
}`);
const r = await Bun.$`cd ${d} && cargo --version && rustc --version && cargo run -q 2>&1`.nothrow().text(); print(r)

